import React, { useState } from 'react'
import { supabase } from '../lib/supabase'

const FONT = "'Clarity City', 'DM Mono', sans-serif"
const MONO = "'DM Mono', monospace"
const BG = '#111114'
const CARD = '#1a1a1e'
const BORDER = '#252528'

export default function PublicLanding({ onEnterCode, onUserLogin }) {
  const [view, setView] = useState('home')
  const [search, setSearch] = useState('')
  const [searchResults, setSearchResults] = useState([])
  const [searching, setSearching] = useState(false)
  const [selectedClient, setSelectedClient] = useState(null)
  const [reqForm, setReqForm] = useState({ firstName:'', note:'' })

  // Signup client form
  const [signupForm, setSignupForm] = useState({
    firstName:'', lastName:'', idNumber:'', submittedBy:'', note:'', username:''
  })

  // User auth
  const [userView, setUserView] = useState('login') // login | signup
  const [userForm, setUserForm] = useState({ username:'', email:'', pin:'', pinConfirm:'' })
  const [userError, setUserError] = useState('')

  const [submitted, setSubmitted] = useState(false)
  const [submitting, setSubmitting] = useState(false)

  const initials = (str) => str ? str.slice(0,2).toUpperCase() : '??'
  const avatarColors = [['#2a1f05','#F5C518'],['#1a1f2e','#85b7eb'],['#1e2a1e','#5dcaa5'],['#2a1a1e','#d85a30'],['#221a2e','#d4537e']]
  const colorFor = (str) => avatarColors[(str||'').charCodeAt(0) % avatarColors.length]

  async function doSearch(val) {
    setSearch(val)
    if (!val.trim()) { setSearchResults([]); return }
    setSearching(true)
    const { data } = await supabase.from('clients').select('id, username, full_name').ilike('username', `%${val}%`).eq('status', 'active').limit(6)
    setSearchResults(data || [])
    setSearching(false)
  }

  async function submitRequest() {
    if (!reqForm.firstName || !selectedClient) return
    setSubmitting(true)
    try {
      await supabase.from('audit_log').insert({
        event_type: 'access_request',
        client_id: selectedClient.id,
        meta: { first_name: reqForm.firstName, note: reqForm.note, client_username: selectedClient.username, requested_at: new Date().toISOString() }
      })
      setSubmitted(true)
    } catch(e) { console.error(e) }
    setSubmitting(false)
  }

  function formatIdNumber(val) {
    const digits = val.replace(/[^0-9a-zA-Z]/g,'')
    let result = ''
    if (digits.length >= 1) result += digits.slice(0,2).replace(/[^0-9]/g,'')
    if (digits.length > 2) result += '-' + digits[2].replace(/[^a-zA-Z]/g,'').toUpperCase()
    if (digits.length > 3) result += '-' + digits.slice(3,7).replace(/[^0-9]/g,'')
    return result
  }

  function handleIdInput(val) {
    setSignupForm(p => ({...p, idNumber: formatIdNumber(val)}))
  }

  async function submitSignup() {
    if (!signupForm.firstName || !signupForm.lastName || !signupForm.username) return
    setSubmitting(true)
    try {
      await supabase.from('clients').insert({
        username: signupForm.username.toLowerCase().replace(/\s/g,''),
        full_name: `${signupForm.firstName} ${signupForm.lastName}`,
        first_name: signupForm.firstName,
        last_name: signupForm.lastName,
        id_number: signupForm.idNumber,
        submitted_by: signupForm.submittedBy,
        submitted_by_name: signupForm.submittedBy,
        signup_note: signupForm.note,
        status: 'pending'
      })
      setSubmitted(true)
    } catch(e) { console.error(e) }
    setSubmitting(false)
  }

  async function handleUserLogin() {
    setUserError('')
    if (!userForm.username || !userForm.pin) { setUserError('Please fill in all fields'); return }
    setSubmitting(true)
    try {
      const { data, error } = await supabase
        .from('registered_users')
        .select('*')
        .eq('username', userForm.username.toLowerCase())
        .eq('pin_hash', userForm.pin)
        .single()
      if (error || !data) { setUserError('Incorrect username or PIN'); setSubmitting(false); return }
      await supabase.from('registered_users').update({ last_login: new Date().toISOString() }).eq('id', data.id)
      if (onUserLogin) onUserLogin(data)
    } catch(e) { setUserError('Something went wrong') }
    setSubmitting(false)
  }

  async function handleUserSignup() {
    setUserError('')
    if (!userForm.username || !userForm.email || !userForm.pin || !userForm.pinConfirm) {
      setUserError('Please fill in all fields'); return
    }
    if (userForm.pin.length !== 4) { setUserError('PIN must be exactly 4 digits'); return }
    if (userForm.pin !== userForm.pinConfirm) { setUserError('PINs do not match'); return }
    setSubmitting(true)
    try {
      const { error } = await supabase.from('registered_users').insert({
        username: userForm.username.toLowerCase().replace(/\s/g,''),
        email: userForm.email,
        pin_hash: userForm.pin
      })
      if (error) {
        if (error.message.includes('unique')) setUserError('Username or email already taken')
        else setUserError('Signup failed. Try again.')
        setSubmitting(false); return
      }
      setUserView('login')
      setUserForm(p => ({...p, pin:'', pinConfirm:'', email:''}))
      setUserError('Account created! Please log in.')
    } catch(e) { setUserError('Something went wrong') }
    setSubmitting(false)
  }

  const neu = { card: '5px 5px 12px #0a0a0c, -2px -2px 6px #1e1e22' }

  const resetHome = () => {
    setSubmitted(false); setView('home'); setSelectedClient(null)
    setReqForm({ firstName:'', note:'' })
    setSignupForm({ firstName:'', lastName:'', idNumber:'', submittedBy:'', note:'', username:'' })
    setUserError('')
  }

  if (submitted) return (
    <div style={{ ...s.wrap, background: BG, fontFamily: FONT }}>
      <div style={s.header}>
        <div style={s.logoRow}>
          <svg width="30" height="30" viewBox="0 0 36 36" fill="none"><rect width="36" height="36" rx="10" fill={CARD}/><path d="M8 12C8 10.3431 9.34315 9 11 9H25C26.6569 9 28 10.3431 28 12V20C28 21.6569 26.6569 23 25 23H20L15 27V23H11C9.34315 23 8 21.6569 8 20V12Z" fill="#F5C518"/></svg>
          <span style={{ ...s.appName, fontFamily: MONO }}>BANQO</span>
        </div>
      </div>
      <div style={s.centeredBody}>
        <div style={s.successIcon}>✓</div>
        <div style={s.successTitle}>{view === 'request' ? 'Request sent!' : 'Signup submitted!'}</div>
        <div style={{ ...s.successSub, fontFamily: MONO }}>
          {view === 'request' ? "We'll reach out to your client and let you know if they approve." : "Our team will review and reach out to the client shortly."}
        </div>
        <button style={{ ...s.primaryBtn, boxShadow: neu.card, fontFamily: FONT }} onClick={resetHome}>back to home</button>
      </div>
    </div>
  )

  return (
    <div style={{ ...s.wrap, background: BG, fontFamily: FONT }}>
      <div style={s.header}>
        <div style={s.logoRow}>
          <svg width="30" height="30" viewBox="0 0 36 36" fill="none"><rect width="36" height="36" rx="10" fill={CARD}/><path d="M8 12C8 10.3431 9.34315 9 11 9H25C26.6569 9 28 10.3431 28 12V20C28 21.6569 26.6569 23 25 23H20L15 27V23H11C9.34315 23 8 21.6569 8 20V12Z" fill="#F5C518"/></svg>
          <span style={{ ...s.appName, fontFamily: MONO }}>BANQO</span>
        </div>
      </div>

      {/* HOME */}
      {view === 'home' && (
        <div style={s.body}>
          <div style={s.heroSection}>
            <div style={s.heroTitle}>Welcome to<br/>Banqo.</div>
            <div style={{ ...s.heroSub, fontFamily: MONO }}>Banqo lets trusted people send and receive messages — seamlessly and securely.</div>
          </div>

          {/* ENTER CODE - primary prominent button */}
          <button style={{ ...s.enterCodeBig, boxShadow: neu.card, fontFamily: FONT }} onClick={onEnterCode}>
            ENTER CODE
          </button>

          <div style={{ ...s.dividerRow, fontFamily: MONO }}>
            <div style={s.dividerLine}/><span style={s.dividerText}>or</span><div style={s.dividerLine}/>
          </div>

          <div style={{ ...s.card, boxShadow: neu.card }} onClick={() => setView('request')}>
            <div style={s.cardIcon}>🔑</div>
            <div style={s.cardBody}>
              <div style={s.cardTitle}>Request Access</div>
              <div style={{ ...s.cardSub, fontFamily: MONO }}>Find a client and request a daily access code</div>
            </div>
            <div style={s.cardArrow}>→</div>
          </div>

          <div style={{ ...s.card, boxShadow: neu.card }} onClick={() => setView('signup')}>
            <div style={s.cardIcon}>✚</div>
            <div style={s.cardBody}>
              <div style={s.cardTitle}>Sign Up a Client</div>
              <div style={{ ...s.cardSub, fontFamily: MONO }}>Know someone who'd benefit from Banqo?</div>
            </div>
            <div style={s.cardArrow}>→</div>
          </div>

          <div style={{ ...s.card, boxShadow: neu.card }} onClick={() => setView('userauth')}>
            <div style={s.cardIcon}>👤</div>
            <div style={s.cardBody}>
              <div style={s.cardTitle}>User Account</div>
              <div style={{ ...s.cardSub, fontFamily: MONO }}>Sign in or create your user profile</div>
            </div>
            <div style={s.cardArrow}>→</div>
          </div>
        </div>
      )}

      {/* REQUEST ACCESS - search */}
      {view === 'request' && !selectedClient && (
        <div style={s.body}>
          <button style={s.backLink} onClick={() => setView('home')}>← back</button>
          <div style={s.pageTitle}>Request Access</div>
          <div style={{ ...s.pageSub, fontFamily: MONO }}>Search for a client username</div>
          <div style={{ ...s.searchBar, boxShadow: neu.card }}>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#F5C518" strokeWidth="2" strokeLinecap="round"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
            <input style={{ ...s.searchInput, fontFamily: MONO }} placeholder="search username..." value={search} onChange={e => doSearch(e.target.value)} autoFocus />
          </div>
          {searching && <div style={{ ...s.hint, fontFamily: MONO }}>searching...</div>}
          {!searching && search && searchResults.length === 0 && <div style={{ ...s.hint, fontFamily: MONO }}>no users found</div>}
          {!search && <div style={{ ...s.hint, fontFamily: MONO }}>start typing to find a client</div>}
          <div style={s.resultsList}>
            {searchResults.map(client => {
              const [bg, fg] = colorFor(client.username)
              return (
                <div key={client.id} style={{ ...s.resultItem, boxShadow: neu.card }} onClick={() => setSelectedClient(client)}>
                  <div style={{ ...s.resultAv, background:bg, color:fg }}>{initials(client.username)}</div>
                  <div>
                    <div style={s.resultName}>{client.full_name}</div>
                    <div style={{ ...s.resultHandle, fontFamily: MONO }}>@{client.username}</div>
                  </div>
                  <div style={{ color:'#F5C518', marginLeft:'auto' }}>→</div>
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* REQUEST ACCESS - form */}
      {view === 'request' && selectedClient && (
        <div style={s.body}>
          <button style={s.backLink} onClick={() => setSelectedClient(null)}>← back</button>
          <div style={s.pageTitle}>Request to @{selectedClient.username}</div>
          <div style={{ ...s.pageSub, fontFamily: MONO }}>Leave a note for the client — we'll pass it along</div>
          <div style={{ ...s.formCard, boxShadow: neu.card }}>
            <div style={{ ...s.formLabel, fontFamily: MONO }}>your first name</div>
            <input style={{ ...s.formInput, fontFamily: FONT }} placeholder="e.g. Rachel" value={reqForm.firstName} onChange={e => setReqForm(p => ({...p, firstName: e.target.value}))} />
            <div style={{ ...s.formLabel, fontFamily: MONO }}>note to {selectedClient.full_name?.split(' ')[0] || 'client'} (optional)</div>
            <textarea style={{ ...s.formTextarea, fontFamily: FONT }} placeholder={`Hey, it's me! I'm here to help if you need me.`}
              value={reqForm.note} onChange={e => setReqForm(p => ({...p, note: e.target.value}))} rows={4} />
            <button style={{ ...s.primaryBtn, opacity: !reqForm.firstName || submitting ? 0.4 : 1, fontFamily: FONT }}
              disabled={!reqForm.firstName || submitting} onClick={submitRequest}>
              {submitting ? 'sending...' : 'send request'}
            </button>
          </div>
        </div>
      )}

      {/* SIGN UP CLIENT */}
      {view === 'signup' && (
        <div style={s.body}>
          <button style={s.backLink} onClick={() => setView('home')}>← back</button>
          <div style={s.pageTitle}>Sign Up a Client</div>
          <div style={{ ...s.pageSub, fontFamily: MONO }}>We'll review and reach out to the client</div>
          <div style={{ ...s.formCard, boxShadow: neu.card }}>
            <div style={{ ...s.formLabel, fontFamily: MONO }}>desired username</div>
            <input style={{ ...s.formInput, fontFamily: MONO }} placeholder="e.g. philcool" value={signupForm.username} onChange={e => setSignupForm(p => ({...p, username: e.target.value}))} />
            <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12 }}>
              <div>
                <div style={{ ...s.formLabel, fontFamily: MONO }}>first name</div>
                <input style={{ ...s.formInput, fontFamily: FONT }} placeholder="Phil" value={signupForm.firstName} onChange={e => setSignupForm(p => ({...p, firstName: e.target.value}))} />
              </div>
              <div>
                <div style={{ ...s.formLabel, fontFamily: MONO }}>last name</div>
                <input style={{ ...s.formInput, fontFamily: FONT }} placeholder="Johnson" value={signupForm.lastName} onChange={e => setSignupForm(p => ({...p, lastName: e.target.value}))} />
              </div>
            </div>
            <div style={{ ...s.formLabel, fontFamily: MONO }}>identification number</div>
            <input style={{ ...s.formInput, fontFamily: MONO }} placeholder="47-B-3291" value={signupForm.idNumber}
              onChange={e => handleIdInput(e.target.value)} maxLength={9} />
            <div style={{ ...s.idHint, fontFamily: MONO }}>format: 00-A-0000</div>
            <div style={{ ...s.formLabel, fontFamily: MONO }}>submitted by (your name)</div>
            <input style={{ ...s.formInput, fontFamily: FONT }} placeholder="Your name" value={signupForm.submittedBy} onChange={e => setSignupForm(p => ({...p, submittedBy: e.target.value}))} />
            <div style={{ ...s.formLabel, fontFamily: MONO }}>send a note (optional)</div>
            <textarea style={{ ...s.formTextarea, fontFamily: FONT }} placeholder="Anything we should know about this client..."
              value={signupForm.note} onChange={e => setSignupForm(p => ({...p, note: e.target.value}))} rows={3} />
            <button style={{ ...s.primaryBtn, opacity: (!signupForm.firstName || !signupForm.lastName || !signupForm.username || submitting) ? 0.4 : 1, fontFamily: FONT }}
              disabled={!signupForm.firstName || !signupForm.lastName || !signupForm.username || submitting} onClick={submitSignup}>
              {submitting ? 'submitting...' : 'submit'}
            </button>
          </div>
        </div>
      )}

      {/* USER AUTH */}
      {view === 'userauth' && (
        <div style={s.body}>
          <button style={s.backLink} onClick={() => { setView('home'); setUserError('') }}>← back</button>
          <div style={s.pageTitle}>{userView === 'login' ? 'Sign In' : 'Create Account'}</div>

          <div style={{ ...s.formCard, boxShadow: neu.card }}>
            <div style={{ ...s.formLabel, fontFamily: MONO }}>username</div>
            <input style={{ ...s.formInput, fontFamily: MONO }} placeholder="your username" value={userForm.username} onChange={e => setUserForm(p => ({...p, username: e.target.value}))} />

            {userView === 'signup' && (
              <>
                <div style={{ ...s.formLabel, fontFamily: MONO }}>email address</div>
                <input style={{ ...s.formInput, fontFamily: MONO }} type="email" placeholder="you@email.com" value={userForm.email} onChange={e => setUserForm(p => ({...p, email: e.target.value}))} />
              </>
            )}

            <div style={{ ...s.formLabel, fontFamily: MONO }}>4-digit PIN</div>
            <input style={{ ...s.formInput, fontFamily: MONO }} type="password" placeholder="••••" maxLength={4}
              value={userForm.pin} onChange={e => setUserForm(p => ({...p, pin: e.target.value.replace(/\D/g,'').slice(0,4)}))} />

            {userView === 'signup' && (
              <>
                <div style={{ ...s.formLabel, fontFamily: MONO }}>confirm PIN</div>
                <input style={{ ...s.formInput, fontFamily: MONO }} type="password" placeholder="••••" maxLength={4}
                  value={userForm.pinConfirm} onChange={e => setUserForm(p => ({...p, pinConfirm: e.target.value.replace(/\D/g,'').slice(0,4)}))} />
              </>
            )}

            {userError && <div style={{ ...s.errorMsg, fontFamily: MONO }}>{userError}</div>}

            <button style={{ ...s.primaryBtn, fontFamily: FONT, opacity: submitting ? 0.4 : 1 }}
              disabled={submitting}
              onClick={userView === 'login' ? handleUserLogin : handleUserSignup}>
              {submitting ? 'please wait...' : userView === 'login' ? 'sign in' : 'create account'}
            </button>

            <button style={{ ...s.switchBtn, fontFamily: MONO }}
              onClick={() => { setUserView(v => v === 'login' ? 'signup' : 'login'); setUserError('') }}>
              {userView === 'login' ? "don't have an account? sign up →" : "already have an account? sign in →"}
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

const s = {
  wrap: { minHeight:'100vh', display:'flex', flexDirection:'column', color:'#ffffff', maxWidth:480, margin:'0 auto' },
  header: { padding:'18px 20px 14px', borderBottom:'0.5px solid #252528', display:'flex', alignItems:'center', justifyContent:'space-between', flexShrink:0 },
  logoRow: { display:'flex', alignItems:'center', gap:10 },
  appName: { fontSize:14, fontWeight:700, color:'#F5C518', letterSpacing:'0.2em' },
  body: { flex:1, padding:'24px 20px', display:'flex', flexDirection:'column', gap:14 },
  heroSection: { marginBottom:4 },
  heroTitle: { fontSize:32, fontWeight:700, color:'#ffffff', lineHeight:1.2, marginBottom:12 },
  heroSub: { fontSize:14, color:'#888aa0', lineHeight:1.6 },
  enterCodeBig: { background:'#F5C518', border:'none', color:'#111114', fontSize:17, fontWeight:700, padding:'18px', borderRadius:14, cursor:'pointer', letterSpacing:'0.15em', width:'100%', display:'block' },
  dividerRow: { display:'flex', alignItems:'center', gap:12, fontSize:11, color:'#444' },
  dividerLine: { flex:1, height:'0.5px', background:'#252528' },
  dividerText: { flexShrink:0 },
  card: { background:'#1a1a1e', border:'0.5px solid #252528', borderRadius:16, padding:'18px 16px', display:'flex', alignItems:'center', gap:14, cursor:'pointer' },
  cardIcon: { fontSize:26, flexShrink:0 },
  cardBody: { flex:1 },
  cardTitle: { fontSize:16, fontWeight:700, color:'#ffffff', marginBottom:4 },
  cardSub: { fontSize:13, color:'#888aa0' },
  cardArrow: { fontSize:20, color:'#F5C518', flexShrink:0 },
  backLink: { background:'none', border:'none', color:'#F5C518', fontSize:14, cursor:'pointer', padding:0, textAlign:'left' },
  pageTitle: { fontSize:24, fontWeight:700, color:'#ffffff', marginBottom:4 },
  pageSub: { fontSize:13, color:'#888aa0', marginBottom:4 },
  searchBar: { background:'#1a1a1e', border:'0.5px solid #252528', borderRadius:14, display:'flex', alignItems:'center', gap:10, padding:'12px 16px' },
  searchInput: { background:'none', border:'none', outline:'none', color:'#ffffff', fontSize:15, width:'100%' },
  hint: { textAlign:'center', color:'#444', fontSize:13, padding:'16px 0' },
  resultsList: { display:'flex', flexDirection:'column', gap:10 },
  resultItem: { background:'#1a1a1e', border:'0.5px solid #252528', borderRadius:14, padding:'14px 16px', display:'flex', alignItems:'center', gap:12, cursor:'pointer' },
  resultAv: { width:44, height:44, borderRadius:12, fontSize:15, fontWeight:700, display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 },
  resultName: { fontSize:15, fontWeight:700, color:'#ffffff' },
  resultHandle: { fontSize:12, color:'#888aa0', marginTop:2 },
  formCard: { background:'#1a1a1e', border:'0.5px solid #252528', borderRadius:16, padding:18 },
  formLabel: { fontSize:10, color:'#888aa0', textTransform:'uppercase', letterSpacing:'0.1em', marginBottom:6 },
  formInput: { background:'#111114', border:'0.5px solid #252528', borderRadius:8, color:'#ffffff', fontSize:15, padding:'11px 14px', width:'100%', outline:'none', marginBottom:14, display:'block', boxSizing:'border-box' },
  formTextarea: { background:'#111114', border:'0.5px solid #252528', borderRadius:8, color:'#ffffff', fontSize:15, padding:'11px 14px', width:'100%', outline:'none', marginBottom:14, display:'block', boxSizing:'border-box', resize:'none', lineHeight:1.5 },
  idHint: { fontSize:10, color:'#444', marginTop:-10, marginBottom:14 },
  primaryBtn: { background:'#F5C518', border:'none', color:'#111114', fontSize:16, fontWeight:700, padding:'13px', borderRadius:12, cursor:'pointer', width:'100%', display:'block', marginTop:4 },
  centeredBody: { flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'40px 32px', textAlign:'center', gap:16 },
  successIcon: { width:64, height:64, borderRadius:'50%', background:'#2a1f05', border:'2px solid #F5C518', display:'flex', alignItems:'center', justifyContent:'center', fontSize:28, color:'#F5C518' },
  successTitle: { fontSize:24, fontWeight:700, color:'#ffffff' },
  successSub: { fontSize:14, color:'#888aa0', lineHeight:1.6 },
  errorMsg: { fontSize:12, color:'#e24b4a', marginBottom:12, padding:'8px 12px', background:'#2a1414', borderRadius:8 },
  switchBtn: { background:'none', border:'none', color:'#F5C518', fontSize:13, cursor:'pointer', width:'100%', textAlign:'center', marginTop:12, padding:8 },
}
